$(function(){

    var menuItems = document.querySelectorAll('li.has-submenu');
    var timer;
    var timer2;
    Array.prototype.forEach.call(menuItems, function(el, i){

        var activatingA = el.querySelector('a');
        var btn = '<button><i class="fa fa-angle-down"></i></button>';
        activatingA.insertAdjacentHTML('afterend', btn);

        el.querySelector('button').addEventListener("click",  function(event){
            if (this.parentNode.className == "has-submenu") {
                this.parentNode.className = "has-submenu open";
                this.parentNode.querySelector('a').setAttribute('aria-expanded', "true");
                this.parentNode.querySelector('button').setAttribute('aria-expanded', "true");
            } else {
                this.parentNode.className = "has-submenu";
                this.parentNode.querySelector('a').setAttribute('aria-expanded', "false");
                this.parentNode.querySelector('button').setAttribute('aria-expanded', "false");
            }
            event.preventDefault();
        });

        var links = el.querySelectorAll('a');
        Array.prototype.forEach.call(links, function(el, i){
            el.addEventListener("focus", function() {

                if (timer2) {
                    if(this.parentNode.parentNode.className == "submenu")
                    {
                        clearTimeout(timer2);
                        timer2 = null;
                    }
                }
            });
            el.addEventListener("blur", function(event) {
                timer2 = setTimeout(function () {
                    var opennav = document.querySelector("#menu .has-submenu.open")
                    if (opennav) {
                        opennav.className = "has-submenu";
                        opennav.querySelector('a').setAttribute('aria-expanded', "false");
                        opennav.querySelector('button').setAttribute('aria-expanded', "false");
                    }
                }, 10);
            });
        });


    });

    // Aquest tall de codi contola el disseny de la capçalera segons scroll quan estem a la home.
    // Si el header té class "home" anirà alternant la class "sobreposat" segons la distància de scroll respecte la part superior de la pantalla


        $(window).on("load scroll",function(){
            if($("body.home").length > 0)
            {
                if($("html").scrollTop() > 200)
                {
                    $("header").removeClass('sobreposat');
                }
                else
                {
                    $("header").addClass('sobreposat');
                }
            }

            if($("html").scrollTop() > 200)
            {
                $("header").removeClass('top');
            }
            else
            {
                $("header").addClass('top');
            }


        });


    // Aquest tall controla el comportament dels menús en mòbils.
    // Simplement mira si existeix contingut desplegable. Si en té, el mostra, sinó segueix el comportament normal del propi link.

    $("#menu a").click(function(event){


        if($(window).width() <= mida_tablet_mobile && $(this).parent().children("ul").length > 0)
        {

            event.preventDefault();
            $(this).parent().toggleClass("desplegat");
        }

    });

    // El mateix que el menú principal aplicat al del peu

    $("#menu_peu a").click(function(event){
        if($(window).width() <= mida_tablet_mobile && $(this).parent().children("div").length > 0)
        {
            event.preventDefault();
            $(this).parent().toggleClass("desplegat");
        }

    });

    /*$('#slide_galeries_inspai').owlCarousel({
        loop:false,
        navText: ['<span class="boto_rodo" id="prev_inspai"><i class="fal fa-arrow-left"></i></span>','<span class="boto_rodo" id="next_inspai"><i class="fal fa-arrow-right"></i></span>'],
        margin:0,
        items:1,
        nav:true,
        dots: true,
        dotsData: true
    });*/

    $('#slide_galeries_inspai').slick({
        infinite: false,
        prevArrow: '<button type="button" class="boto_rodo" id="prev_inspai"><i class="fal fa-arrow-left"></i></button>',
        nextArrow: '<button type="button" class="boto_rodo" id="next_inspai"><i class="fal fa-arrow-right"></i></button>'

    });

    $('#slide_blog').owlCarousel({
        loop:true,
        margin:0,
        items:1,
        nav:false
    });

    $(".galeria_popup").each(function(){

        $(this).magnificPopup({
            delegate: 'a',
            type: 'image',
            tLoading: 'Loading image #%curr%...',
            mainClass: 'mfp-img-mobile',
            gallery: {
                enabled: true,
                navigateByImgClick: true,
                preload: [0,1] // Will preload 0 - before current, and 1 after the current image
            },
            image: {
                tError: '<a href="%url%">The image #%curr%</a> could not be loaded.',

            },
            callbacks: {
                elementParse: function(item) {
                    // the class name
                    console.log(item.el[0].className);
                    if(item.el[0].className.indexOf('video-link') !== -1 ) {
                        item.type = 'iframe';
                    } else {
                        item.type = 'image';
                    }
                }
            }
        });

    });

});

function toggle_desplegable(id)
{
    $("#desplegable_"+id).toggleClass('actiu');
    $("#desplegable_"+id+" > div").slideToggle();

}

/**
 * Helper: cssEscape - uses native CSS.escape when available, otherwise a conservative fallback
 */
function cssEscape(str) {
    if (typeof str !== 'string') return '';
    if (window.CSS && typeof window.CSS.escape === 'function') {
        return window.CSS.escape(str);
    }
    // conservative fallback: escape characters not allowed in simple IDs
    return str.replace(/[^A-Za-z0-9_\-:\.]/g, function(ch) {
        var hex = ch.charCodeAt(0).toString(16);
        return '\\' + hex + ' ';
    });
}

/**
 * Helper: validateIdStrict
 * - rejects strings that obviously contain HTML or dangerous schemes
 * - ensures the id matches a conservative pattern used by your codebase
 */
function validateIdStrict(id) {
    if (typeof id !== 'string' || id.length === 0) return false;
    // Quick reject obvious HTML or JS pseudo-schemes
    if (id.indexOf('<') !== -1 || id.indexOf('>') !== -1) return false;
    if (/javascript\s*:/i.test(id)) return false;
    // Trim whitespace
    if (/\s/.test(id)) return false;
    // Allow either '#id' or 'id' forms. Then check the raw id against a safe regex.
    var raw = id.charAt(0) === '#' ? id.slice(1) : id;
    // Conservative ID regex: must start with letter, underscore or dash, followed by letters, digits, underscore, dash, colon or dot
    var validIdRegex = /^[A-Za-z_\-][A-Za-z0-9_\-:\.]*$/;
    return validIdRegex.test(raw);
}

/**
 * Secure scroll_to implementation
 * - validates id
 * - builds a safe selector with cssEscape
 * - uses document.querySelector to avoid jQuery interpreting HTML
 */
function scroll_to(id, dif) {
    if (!dif) dif = 0;

    if (!validateIdStrict(id)) {
        console.warn('scroll_to: rejected invalid id');
        return;
    }

    // Normalize raw id without leading '#'
    var raw = id.charAt(0) === '#' ? id.slice(1) : id;
    var escaped = cssEscape(raw);
    var selector = '#' + escaped;

    // Use native DOM lookup to avoid jQuery HTML parsing
    var el = document.querySelector(selector);
    if (!el) return;

    // compute top position
    var top = el.getBoundingClientRect().top + window.pageYOffset + (Number(dif) || 0);

    // prefer smooth scrolling if supported
    if ('scrollBehavior' in document.documentElement.style) {
        window.scrollTo({ top: top, behavior: 'smooth' });
    } else if (window.jQuery) {
        // fallback to jQuery animate if jQuery available
        try {
            $('html,body').animate({ scrollTop: top }, 300);
        } catch (e) {
            window.scrollTo(0, top);
        }
    } else {
        window.scrollTo(0, top);
    }
}